<template>
  <div v-loading="loading||saving||linking" class="app-container strategy-editor">
    <el-alert v-if="loadError" :title="loadError" type="error" :closable="false"/>
    <template v-else>
      <div class="editor-heading"><div><el-button type="text" @click="back"><i class="el-icon-back" aria-hidden="true"/> 返回赠品管理</el-button><h2>{{ form.id?'编辑赠品策略组':'新增赠品策略组' }}</h2><p class="muted">先设置规则，再用模拟购物清单检查赠送结果。适用店铺及组间执行顺序在店铺组中维护。</p></div><el-button v-if="form.id" @click="makeCopy">另存为独立策略组</el-button></div>
      <el-alert v-if="usages.length" :title="`编辑此公共策略会影响 ${usages.length} 个店铺组、${affectedShopCount} 家店铺的新转单：${usages.map(s=>s.name).join('、')}`" type="warning" :closable="false" show-icon/>
      <el-card shadow="never" class="basic-card"><div slot="header"><strong>基本信息</strong><el-tag v-if="form.id" size="small" class="version">版本 {{ form.revision }}</el-tag></div>
        <el-form label-position="top" size="small" class="basic-form"><el-form-item label="策略组名称" required :error="generalError('name')"><el-input v-model="form.name" maxlength="100" show-word-limit placeholder="例如：双十一满额赠礼"/></el-form-item><el-form-item label="订单付款时间范围" required :error="generalError('period')"><el-date-picker v-model="period" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" start-placeholder="开始时间" end-placeholder="结束时间" range-separator="至" style="width:100%"/><div class="muted">按订单付款时间判断是否参加活动。</div></el-form-item></el-form>
      </el-card>
      <el-alert v-if="attempted&&issues.length" :title="`还有 ${issues.length} 项需要完善：${issues[0].message}`" type="error" :closable="false" show-icon class="validation-banner"><el-button type="text" @click="locateIssue">定位第一项</el-button></el-alert>
      <div class="editor-workspace">
        <aside class="rule-directory"><div class="directory-title"><strong>组内规则</strong><span class="muted">{{ form.policy.rules.length }} / 30 条</span></div><p class="muted">从上到下判断，命中后可继续累计赠送或结束本组。</p>
          <div v-for="(r,i) in form.policy.rules" :key="r.key" class="rule-entry" :class="{active:activeKey===r.key}"><button class="rule-select" @click="selectRule(r.key)"><span class="rule-index">{{ String(i+1).padStart(2,'0') }}</span><span><strong>{{ r.name||'未命名规则' }}</strong><small>{{ typeLabel(r.type) }} · {{ r.stop?'命中后结束':'命中后继续' }}</small><small v-if="attempted&&issues.some(e=>e.key===r.key)" class="invalid">待完善配置</small></span></button><div class="directory-actions"><el-button type="text" :disabled="i===0" @click="move(i,-1)">上移</el-button><el-button type="text" :disabled="i===form.policy.rules.length-1" @click="move(i,1)">下移</el-button><el-button type="text" :disabled="form.policy.rules.length>=30" @click="duplicateRule(i)">复制</el-button><el-button type="text" :disabled="form.policy.rules.length===1" @click="removeRule(i)">删除</el-button></div></div>
          <el-button :disabled="form.policy.rules.length>=30" class="add-rule" @click="addRule"><i class="el-icon-plus" aria-hidden="true"/> 添加规则</el-button>
        </aside>
        <main class="rule-panel"><el-tabs v-model="section"><el-tab-pane label="规则配置" name="rules"><template v-if="activeRule">
          <h3>第 {{ activeIndex+1 }} 条 · {{ activeRule.name||'新规则' }}</h3>
          <div class="live-summary"><i class="el-icon-guide"/><span>{{ summary(activeRule) }}</span></div>
          <el-form label-position="top" size="small"><el-form-item label="规则名称" required :error="ruleError('name')"><el-input v-model="activeRule.name" maxlength="100" placeholder="例如：满200元赠保温杯"/></el-form-item>
            <el-form-item label="赠送方式"><div class="type-options"><button v-for="type in types" :key="type.value" class="type-option" :class="{chosen:activeRule.type===type.value}" :aria-pressed="activeRule.type===type.value" @click.prevent="changeType(type.value)"><strong>{{ type.label }}</strong><small class="type-caption">{{ activeRule.type===type.value?'当前配置':'示例' }}</small><span>{{ typeDescription(type) }}</span></button></div></el-form-item>
            <el-form-item label="购买商品范围" required :error="ruleError('skus')"><el-radio-group v-model="activeRule.purchase_scope"><el-radio v-if="activeRule.type==='AMOUNT'" label="ALL">全部购买商品</el-radio><el-radio label="SELECTED">指定商品</el-radio></el-radio-group><div v-if="activeRule.purchase_scope==='ALL'" class="muted scope-note">合计订单购买商品的实付金额，不含运费与OMS追加赠品。</div><gift-product-picker v-else v-model="activeRule.skus" :key="activeRule.key" button-text="选择购买商品 / 批量添加SKU"/></el-form-item>
            <el-form-item v-if="activeRule.type==='AMOUNT'" label="满额门槛" required :error="ruleError('amount')"><el-input-number v-model="activeRule.amount" :min="0" :max="1000000000" :precision="2"/><span class="unit">元</span><div class="muted">所选购买范围内的商品实付合计，不含运费。</div></el-form-item>
            <el-form-item v-if="['PRODUCT','MULTIPLE'].includes(activeRule.type)" :label="activeRule.type==='MULTIPLE'?'每满购买数量':'合计购买数量门槛'" required :error="ruleError('minimum')"><el-input-number v-model="activeRule.minimum" :min="1" :max="100000000" :precision="0"/><span class="unit">件</span><div class="muted">{{ activeRule.type==='PRODUCT'?'达到门槛仅赠送下方数量一次；购买更多不自动倍赠。':'每满一组数量赠送一次，不足一组不计入倍数。' }}</div></el-form-item>
            <el-form-item v-if="activeRule.type==='MULTIPLE'" label="单单倍赠上限" required :error="ruleError('cap')"><el-input-number v-model="activeRule.cap" :min="1" :max="100000" :precision="0"/><span class="unit">倍</span></el-form-item>
            <el-form-item label="活动累计赠送上限" :error="ruleError('max_count')"><el-radio-group :value="activeRule.quota_limited" @input="setQuotaLimit"><el-radio :label="false">不限</el-radio><el-radio :label="true">限制次数</el-radio></el-radio-group><div v-if="activeRule.quota_limited" class="quota-input"><el-input-number v-model="activeRule.max_count" :min="Math.max(1,Number(activeQuota.used_count)||0)" :max="1000000000" :precision="0"/><span class="unit">次</span></div><div v-if="form.id" class="quota-usage"><span>已占用 {{ activeQuota.used_count||0 }} 次</span><span>剩余 {{ activeRule.max_count>0?Math.max(0,activeRule.max_count-(activeQuota.used_count||0))+' 次':'不限' }}</span><el-button type="text" :loading="refreshingQuota" @click="refreshQuota">刷新用量</el-button></div><p class="muted">所有关联店铺共用额度。买多赠多按赠送倍数计次，其他方式命中计1次；每次包含下方配置的整套赠品。额度不足时按剩余次数赠送，耗尽则继续后续策略。</p><p class="muted">从首次设置限额起计数；保存修改或取消限制不清零。生成赠品方案即占用，退款、取消与库存超时不自动返还。</p></el-form-item>
            <template v-if="activeRule.type==='TIER'"><el-alert title="只采用最高满足的阶梯，不累计各档赠品；门槛请从小到大设置。" type="info" :closable="false"/><p v-if="ruleError('tiers')" class="invalid">{{ ruleError('tiers') }}</p><div v-for="(tier,i) in activeRule.tiers" :key="i" class="tier-card"><div class="tier-heading"><strong>阶梯 {{ i+1 }}</strong><el-button type="text" :disabled="activeRule.tiers.length===1" @click="activeRule.tiers.splice(i,1)">删除阶梯</el-button></div><el-form-item label="购买满多少件" required><el-input-number v-model="tier.minimum" :min="1" :max="100000000" :precision="0"/><span class="unit">件</span></el-form-item><gift-reward-table v-model="tier.gifts"/></div><el-button :disabled="activeRule.tiers.length>=20" @click="addTier"><i class="el-icon-plus" aria-hidden="true"/> 添加阶梯</el-button><p v-if="ruleError('gifts')" class="invalid">{{ ruleError('gifts') }}</p></template>
            <el-form-item v-else label="赠送商品与数量" required :error="ruleError('gifts')"><gift-reward-table v-model="activeRule.gifts" :key="activeRule.key"/></el-form-item>
            <el-form-item label="命中这条规则后"><el-radio-group v-model="activeRule.stop"><el-radio :label="false">继续下一条规则，赠品累计</el-radio><el-radio :label="true">结束本组</el-radio></el-radio-group><p class="muted">未命中总会继续下一条。策略组之间是否继续，由店铺组中的关联设置决定。</p></el-form-item>
          </el-form>
        </template></el-tab-pane><el-tab-pane label="库存与售后" name="afterSale"><h3>库存与售后设置</h3><el-form label-position="top" size="small"><el-form-item label="库存不足"><el-tag type="warning">等待补货，暂缓自动履约</el-tag><p class="muted">规则命中不代表库存预占成功。</p></el-form-item><el-form-item label="未发赠品失去资格">自动取消；已下发仓库的先撤回，仓库确认后再释放占用。</el-form-item><el-form-item label="已发赠品失去资格"><el-radio-group v-model="form.policy.shipped_policy"><el-radio label="RETURN">安排退回</el-radio><el-radio label="KEEP">允许保留，不追退</el-radio></el-radio-group></el-form-item><el-form-item label="退差价"><el-checkbox v-model="form.policy.difference_affects_amount">退差价影响满额门槛</el-checkbox></el-form-item><el-form-item label="授权豁免"><el-checkbox v-model="form.policy.allow_waive">允许有权限人员填写依据后豁免追退</el-checkbox></el-form-item></el-form></el-tab-pane>
        <el-tab-pane label="模拟试算" name="simulation"><h3>用未保存配置试算</h3><p class="muted">仅计算当前策略组的赠送结果，参考当前剩余额度，不占赠送次数、不占库存。实际转单以并发申请结果为准。店铺组之间的执行顺序请在店铺组中查看。</p><el-form label-position="top" size="small"><el-form-item label="模拟付款时间" required><el-date-picker v-model="paidTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" placeholder="选择付款时间"/></el-form-item><el-form-item label="模拟购买商品" required><gift-product-picker :value="cart.map(l=>l.sku_sn)" :max="100" :show-selected="false" button-text="选择模拟购买商品" @input="setCart" @products="rememberCart"/></el-form-item><el-table :data="cart" size="small" empty-text="选择购买商品，填写数量和该商品行实付合计"><el-table-column label="商品 / SKU" min-width="170"><template slot-scope="s"><strong>{{ (cartCatalog[s.row.sku_sn]||{}).goodsName||s.row.sku_sn }}</strong><div class="muted sku">{{ s.row.sku_sn }}</div></template></el-table-column><el-table-column label="购买数量" width="160"><template slot-scope="s"><el-input-number v-model="s.row.quantity" :min="1" :max="100000000" :precision="0" size="small" style="width:130px"/></template></el-table-column><el-table-column label="本行实付合计（元）" width="180"><template slot-scope="s"><el-input-number v-model="s.row.payment" :min="0" :max="1000000000" :precision="2" size="small" style="width:150px"/></template></el-table-column><el-table-column width="65"><template slot-scope="s"><el-button type="text" @click="cart.splice(s.$index,1)">移除</el-button></template></el-table-column></el-table></el-form><p class="muted">实付填写整行金额，不是商品单价；不含运费。</p><el-button type="primary" :loading="simulating" @click="simulate">试算未保存配置</el-button>
          <div v-if="trial" class="trial-result"><el-alert v-if="trialStale" title="配置或模拟清单已修改，以下为上次结果，请重新试算。" type="warning" :closable="false"/><h4>{{ trial.gifts.length?'预计赠送':'未命中赠品' }}</h4><div v-for="g in trial.gifts" :key="g.sku_sn" class="trial-gift"><strong>{{ g.goods_name||g.sku_sn }}</strong><span>{{ g.sku_sn }} × {{ g.quantity }} {{ g.sales_unit }}</span></div><div v-for="g in trial.trace" :key="g.group_id"><p>{{ g.reason }}</p><div v-for="r in g.rules" :key="r.key" class="trial-rule"><el-tag size="mini" :type="r.skipped?'info':r.matched?'success':'warning'">{{ r.skipped?'未执行':r.matched?'命中':'未命中' }}</el-tag><strong>{{ r.name }}</strong><span>{{ r.reason }}</span><span v-if="!r.skipped&&r.requested_count" class="muted">预计消耗 {{ r.granted_count }} 次 / 原应赠 {{ r.requested_count }} 次</span><span v-if="!r.skipped" class="muted">购买 {{ r.basis_quantity }} 件 / 实付 {{ r.basis_amount }} 元</span></div></div></div>
        </el-tab-pane></el-tabs></main>
      </div>
      <el-alert v-if="associationError" :title="associationError" type="warning" :closable="false" class="validation-banner"/>
      <div v-if="savedState&&!dirty" class="saved-result"><i class="el-icon-success"/><div><strong>策略组已保存为{{ form.enabled?'启用':'停用' }}，版本 {{ form.revision }}</strong><p class="muted">{{ usages.length?`已关联 ${usages.length} 个店铺组。`:'尚未关联店铺组，暂不参与赠送。' }}{{ !form.enabled?'停用策略不会参与赠送。':'' }}</p></div><el-button @click="openAssociation">关联到店铺组</el-button><el-button type="primary" plain @click="back"><i class="el-icon-back" aria-hidden="true"/> 返回赠品管理</el-button></div>
      <footer class="editor-footer"><div class="footer-status"><span>{{ !form.id?'新策略尚未保存':dirty?'有未保存修改':'配置已同步' }}</span><span v-if="originScope" class="muted">来自：{{ originScope.name }}</span><el-checkbox v-if="originScope&&!form.id" v-model="linkAfterSave">保存后关联并返回此店铺组</el-checkbox></div><el-button @click="back">返回</el-button><el-button :loading="saving" :disabled="loading" @click="save(false)">保存为停用</el-button><el-button type="primary" :loading="saving" :disabled="loading" @click="save(true)">{{ form.id?'保存并更新为启用':'保存并启用' }}</el-button></footer>
      <el-dialog title="关联到店铺组" :visible.sync="associationVisible" width="min(650px, 95vw)" append-to-body :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="选择店铺组"><el-select v-model="associateScopeId" style="width:100%" filterable @change="chooseAssociation"><el-option v-for="s in scopes" :key="s.id" :value="s.id" :label="s.name+(s.enabled?'':'（停用）')" :disabled="s.links.some(l=>Number(l.group_id)===Number(form.id))"/></el-select></el-form-item><template v-if="associateSnapshot"><p>将追加为第 {{ associateSnapshot.links.length+1 }} 个策略组。前序策略若命中后停止，本组不会执行。</p><el-form-item label="命中当前策略组后"><el-radio-group v-model="associateContinue"><el-radio :label="false">停止后续策略组</el-radio><el-radio :label="true">继续下一策略组</el-radio></el-radio-group></el-form-item><p class="muted">{{ form.enabled?'':'当前策略已停用，关联后仍不会参与赠送。' }}{{ associateSnapshot.enabled?'':'该店铺组已停用，启用后才会参与赠送。' }}</p></template></el-form><span slot="footer"><el-button @click="associationVisible=false">取消</el-button><el-button type="primary" :disabled="!associateSnapshot" :loading="linking" @click="linkSaved">保存关联并返回店铺组</el-button></span></el-dialog>
    </template>
  </div>
</template>
<script>
import * as api from '@/api/order/gift'
import GiftProductPicker from './GiftProductPicker'
import GiftRewardTable from './GiftRewardTable'
import { clone, draftFrom, draftIssues, newGiftRule, ruleSummary, strategyPayload, giftTypes } from './giftStrategy'
export default {
  name:'GiftStrategyEditor',components:{GiftProductPicker,GiftRewardTable},
  data:()=>({loading:true,loadError:'',quotaUsage:{},refreshingQuota:false,form:draftFrom(),period:[],scopes:[],activeKey:'',section:'rules',types:giftTypes,attempted:false,baseline:'',saving:false,savedState:false,allowLeave:false,linkAfterSave:false,associationVisible:false,associateScopeId:null,associateSnapshot:null,associateContinue:false,linking:false,associationError:'',cart:[],cartCatalog:{},paidTime:'',trial:null,trialFingerprint:'',simulationVersion:0,simulating:false}),
  computed:{
    activeQuota(){return this.activeRule?this.quotaUsage[this.activeRule.key]||{}:{}},
    activeIndex(){return this.form.policy.rules.findIndex(r=>r.key===this.activeKey)},activeRule(){return this.form.policy.rules[this.activeIndex]},
    fingerprint(){return JSON.stringify({form:this.form,period:this.period})},dirty(){return !!this.baseline&&this.fingerprint!==this.baseline},
    issues(){return draftIssues(this.form,this.period)},usages(){return this.scopes.filter(s=>s.links.some(l=>Number(l.group_id)===Number(this.form.id)))},affectedShopCount(){return new Set(this.usages.flatMap(s=>s.channels)).size},
    originScope(){return this.scopes.find(s=>Number(s.id)===Number(this.$route.query.scope))},
    simulationFingerprint(){return JSON.stringify({group_id:this.form.id||0,policy:strategyPayload(this.form,this.period).policy,paid:this.paidTime,cart:this.cart,quotaUsage:this.quotaUsage})},trialStale(){return this.trialFingerprint!==this.simulationFingerprint}
  },
  async created(){await this.load()},mounted(){window.addEventListener('beforeunload',this.unload)},beforeDestroy(){window.removeEventListener('beforeunload',this.unload)},
  beforeRouteLeave(to,from,next){if((this.saving||this.linking)&&!this.allowLeave){this.$message.warning('正在保存，请稍候');return next(false)}if(!this.dirty)return next();this.$confirm('当前修改尚未保存，是否离开？','未保存修改',{confirmButtonText:'离开',cancelButtonText:'继续编辑',type:'warning'}).then(()=>next()).catch(()=>next(false))},
  methods:{
    summary:ruleSummary,typeLabel(type){return (giftTypes.find(t=>t.value===type)||{}).label},
    typeDescription(type){
      const rule=this.activeRule;if(!rule||type.value!==rule.type)return type.example;
      const minimum=rule.minimum==null?'待设置':rule.minimum,cap=rule.cap==null?'待设置':rule.cap;
      if(rule.type==='AMOUNT')return `商品实付满${rule.amount==null?'待设置':rule.amount}元，赠送下方配置的赠品`;
      if(rule.type==='PRODUCT')return `指定商品合计满${minimum}件，赠送一次`;
      if(rule.type==='MULTIPLE')return `每满${minimum}件指定商品赠送一次，最多${cap}倍`;
      return `已配置${(rule.tiers||[]).length}个阶梯，按最高满足档赠送`;
    },
    async load(){try{const [groups,scopes]=await Promise.all([api.giftGroups(),api.giftShopGroups()]);this.scopes=scopes.data;const id=this.$route.query.id||this.$route.query.copy;const row=id?groups.data.find(g=>String(g.id)===String(id)):null;if(id&&!row)throw Error('策略组不存在或无权访问，请返回后刷新列表');this.form=draftFrom(row,!!this.$route.query.copy);this.quotaUsage=this.$route.query.copy?{}:(row&&row.quota_usage)||{};this.period=row?[row.policy.start_time,row.policy.end_time]:[];this.activeKey=this.form.policy.rules[0].key;this.linkAfterSave=!!this.originScope&&!row;this.baseline=this.fingerprint}catch(error){this.loadError=error.message||'配置读取失败，请返回后重试'}finally{this.loading=false}},
    unload(event){if(this.dirty){event.preventDefault();event.returnValue=''}},
    back(scope){const id=typeof scope==='number'||typeof scope==='string'?scope:this.$route.query.scope;if(this.saving||this.linking)this.allowLeave=true;this.$router.push({path:'/oms-order/gifts',query:id?{scopeId:String(id)}:{}})},
    generalError(field){return this.attempted?(this.issues.find(e=>!e.key&&e.field===field)||{}).message:''},ruleError(field){return this.attempted?(this.issues.find(e=>e.key===this.activeKey&&e.field===field)||{}).message:''},
    locateIssue(){const issue=this.issues[0];if(issue&&issue.key){this.activeKey=issue.key;this.section='rules'}this.$nextTick(()=>{const el=this.$el.querySelector('.el-form-item__error');if(el)el.scrollIntoView({block:'center',behavior:'smooth'})})},
    selectRule(key){this.activeKey=key;this.section='rules'},addRule(){const rule=newGiftRule();this.form.policy.rules.push(rule);this.selectRule(rule.key)},
    move(index,delta){const rules=this.form.policy.rules;if(index+delta<0||index+delta>=rules.length)return;const rule=rules.splice(index,1)[0];rules.splice(index+delta,0,rule)},
    duplicateRule(index){if(this.form.policy.rules.length>=30)return;const copy=clone(this.form.policy.rules[index]);copy.key=newGiftRule().key;copy.name=copy.name.slice(0,94)+'（副本）';this.form.policy.rules.splice(index+1,0,copy);this.selectRule(copy.key)},
    removeRule(index){if(this.form.policy.rules.length<=1)return;this.form.policy.rules.splice(index,1);if(!this.form.policy.rules.some(r=>r.key===this.activeKey))this.selectRule(this.form.policy.rules[Math.min(index,this.form.policy.rules.length-1)].key)},
    changeType(type){this.activeRule.type=type;if(type!=='AMOUNT')this.activeRule.purchase_scope='SELECTED';if(type==='TIER'&&!this.activeRule.tiers.length)this.activeRule.tiers=[{minimum:2,gifts:[]}]},
    addTier(){const tiers=this.activeRule.tiers;tiers.push({minimum:Number(tiers[tiers.length-1].minimum)+1,gifts:[]})},
    setQuotaLimit(limited){this.activeRule.quota_limited=limited;this.activeRule.max_count=limited?Math.max(1000,Number(this.activeQuota.used_count)||0):0},
    async refreshQuota(){if(!this.form.id)return;const id=this.form.id;this.refreshingQuota=true;try{const row=(await api.giftGroups()).data.find(g=>Number(g.id)===Number(id));if(row&&this.form.id===id)this.quotaUsage=row.quota_usage||{}}finally{this.refreshingQuota=false}},
    makeCopy(){this.form=draftFrom(this.form,true);this.quotaUsage={};this.savedState=false;this.linkAfterSave=false;this.associationError='';this.$message.info('已复制到独立的新策略，保存前可继续调整')},
    async save(enable){if(this.saving||this.linking)return;this.attempted=true;if(this.issues.length){this.locateIssue();return}this.saving=true;this.associationError='';let persisted=false;const shouldLink=this.linkAfterSave&&!this.form.id&&this.originScope;try{const payload=strategyPayload(this.form,this.period);payload.enabled=enable?1:0;const saved=(await api.saveGiftGroup(payload)).data;this.form={...this.form,id:saved.id,revision:saved.revision,enabled:saved.enabled};this.quotaUsage=saved.quota_usage||{};persisted=true;this.baseline=this.fingerprint;this.savedState=true;this.$message.success('策略组已保存为'+(enable?'启用':'停用'));await this.$router.replace({path:'/oms-order/gift-editor/index',query:{id:String(saved.id),...(this.$route.query.scope?{scope:this.$route.query.scope}:{})}});if(shouldLink){this.associateSnapshot=clone(shouldLink);this.associateContinue=false;await this.attach();return}this.scopes=(await api.giftShopGroups()).data}catch(error){if(persisted)this.associationError='策略已保存，关联或列表刷新未完成，请核对后重试；不会重复创建策略。'}finally{this.saving=false}},
    async openAssociation(){this.scopes=(await api.giftShopGroups()).data;this.associateScopeId=null;this.associateSnapshot=null;this.associateContinue=false;this.associationVisible=true},
    chooseAssociation(){const selected=this.scopes.find(s=>Number(s.id)===Number(this.associateScopeId));this.associateSnapshot=selected?clone(selected):null},
    async attach(){const scope=clone(this.associateSnapshot);if(!scope)throw Error('请选择店铺组');if(!scope.links.some(l=>Number(l.group_id)===Number(this.form.id))){scope.links.push({group_id:this.form.id,continue_after_match:this.associateContinue});await api.saveGiftShopGroup(scope)}this.associationVisible=false;this.$message.success('已关联到店铺组');this.baseline=this.fingerprint;this.back(scope.id)},
    async linkSaved(){this.linking=true;try{await this.attach()}catch(error){this.associationError='策略已保存，店铺组关联未完成。请刷新店铺组版本后重新选择并关联。'}finally{this.linking=false}},
    rememberCart(rows){rows.forEach(r=>this.$set(this.cartCatalog,r.skuSn,r))},setCart(skus){const old=new Map(this.cart.map(l=>[l.sku_sn,l]));this.cart=skus.map(sku=>old.get(sku)||{sku_sn:sku,quantity:1,payment:0})},
    async simulate(){this.attempted=true;if(this.issues.length){this.locateIssue();return}if(!this.paidTime||!this.cart.length)return this.$message.warning('请选择模拟付款时间和购买商品');const version=++this.simulationVersion,fingerprint=this.simulationFingerprint;this.simulating=true;try{const result=(await api.simulateGiftStrategy({group_id:this.form.id||0,name:this.form.name,policy:strategyPayload(this.form,this.period).policy,paid_time:this.paidTime,lines:clone(this.cart)})).data;if(version===this.simulationVersion){this.trial=result;this.trialFingerprint=fingerprint}}finally{if(version===this.simulationVersion)this.simulating=false}}
  }
}
</script>
